// LoadFromPath loads the pkl module at the given path and evaluates it into a Reconcile
export const loadFromPath = async (path: string): Promise<Reconcile> => {
  const evaluator = await pklTypescript.newEvaluator(pklTypescript.PreconfiguredOptions);
  try {
    const result = await load(evaluator, pklTypescript.FileSource(path));
    return result
  } finally {
    evaluator.close()
  }
};

export const load = (evaluator: pklTypescript.Evaluator, source: pklTypescript.ModuleSource): Promise<Reconcile> =>
  evaluator.evaluateModule(source) as Promise<Reconcile>;
